import argparse


def transform(text, upper=False, reverse=False):
    if upper:
        text = text.upper()
    if reverse:
        text = text[::-1]
    return text


def main(argv=None):
    parser = argparse.ArgumentParser(description="Apply a transform to TEXT.")
    parser.add_argument("--upper", action="store_true", help="uppercase the text")
    parser.add_argument("--reverse", action="store_true", help="reverse the text")
    parser.add_argument("text", nargs="*", metavar="TEXT")
    args = parser.parse_args(argv)

    if not args.text:
        parser.error("the following arguments are required: TEXT")

    joined = " ".join(args.text)
    print(transform(joined, upper=args.upper, reverse=args.reverse))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
